-- Referrals, points, and freebies. One store per row.
-- NULL tenant_id is the owner store. Review and run this yourself after 0027.
-- Do not apply 0022. Codes are generated by the app, not backfilled here.

alter table customers
  add column if not exists referral_code text,
  add column if not exists referred_by_customer_id uuid references customers(id),
  add column if not exists referred_at timestamptz;

create unique index if not exists customers_referral_code_per_store
  on customers (
    (coalesce(bot_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    referral_code
  )
  where referral_code is not null;

create table if not exists referrals (
  id uuid primary key default gen_random_uuid(),
  bot_id uuid references bot_connections(id) on delete cascade,
  tenant_id uuid references tenants(id) on delete cascade,
  referrer_customer_id uuid not null references customers(id) on delete cascade,
  referred_customer_id uuid not null references customers(id) on delete cascade,
  status text not null check (status in ('pending', 'qualified', 'rejected')),
  qualified_order_id uuid references orders(id),
  reject_reason text,
  created_at timestamptz not null default now(),
  qualified_at timestamptz,
  joined_notified_at timestamptz,
  referrer_notified_at timestamptz,
  constraint referrals_not_self check (referrer_customer_id <> referred_customer_id)
);

create unique index if not exists referrals_one_referred_per_store
  on referrals (
    (coalesce(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    referred_customer_id
  );

create index if not exists referrals_pending_sweep
  on referrals (status, created_at)
  where status = 'pending';

create index if not exists referrals_referrer_qualified
  on referrals (referrer_customer_id, qualified_at)
  where status = 'qualified';

create table if not exists points_ledger (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references customers(id) on delete cascade,
  tenant_id uuid references tenants(id) on delete cascade,
  delta integer not null check (delta <> 0),
  reason text not null check (reason in ('referral_reward', 'redeem_to_wallet', 'admin_adjust')),
  reference text not null,
  note text,
  created_at timestamptz not null default now(),
  unique (customer_id, reason, reference)
);

create index if not exists points_ledger_customer
  on points_ledger (customer_id, created_at);

create table if not exists freebies (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 80),
  description text not null default '' check (char_length(description) <= 400),
  kind text not null check (kind in ('text', 'link')),
  content text not null check (char_length(content) between 1 and 2000),
  required_referrals int not null default 2 check (required_referrals >= 0),
  active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists freebies_store_sort
  on freebies (
    (coalesce(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    sort_order,
    created_at
  );

create table if not exists freebie_claims (
  id uuid primary key default gen_random_uuid(),
  freebie_id uuid not null references freebies(id) on delete cascade,
  customer_id uuid not null references customers(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (freebie_id, customer_id)
);

alter table referrals enable row level security;
alter table points_ledger enable row level security;
alter table freebies enable row level security;
alter table freebie_claims enable row level security;

drop policy if exists "referrals_owner_read" on referrals;
create policy "referrals_owner_read" on referrals for select
  using (tenant_id is null and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner');
drop policy if exists "referrals_reseller_read" on referrals;
create policy "referrals_reseller_read" on referrals for select
  using (tenant_id is not null and tenant_id in (select id from tenants where owner_user_id = auth.uid()));

drop policy if exists "points_ledger_owner_read" on points_ledger;
create policy "points_ledger_owner_read" on points_ledger for select
  using (tenant_id is null and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner');
drop policy if exists "points_ledger_reseller_read" on points_ledger;
create policy "points_ledger_reseller_read" on points_ledger for select
  using (tenant_id is not null and tenant_id in (select id from tenants where owner_user_id = auth.uid()));

drop policy if exists "freebies_owner_read" on freebies;
create policy "freebies_owner_read" on freebies for select
  using (tenant_id is null and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner');
drop policy if exists "freebies_reseller_read" on freebies;
create policy "freebies_reseller_read" on freebies for select
  using (tenant_id is not null and tenant_id in (select id from tenants where owner_user_id = auth.uid()));

drop policy if exists "freebie_claims_owner_read" on freebie_claims;
create policy "freebie_claims_owner_read" on freebie_claims for select
  using (
    (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner'
    and exists (select 1 from freebies where freebies.id = freebie_id and freebies.tenant_id is null)
  );
drop policy if exists "freebie_claims_reseller_read" on freebie_claims;
create policy "freebie_claims_reseller_read" on freebie_claims for select
  using (
    exists (
      select 1 from freebies
      where freebies.id = freebie_id
        and freebies.tenant_id is not null
        and freebies.tenant_id in (select id from tenants where owner_user_id = auth.uid())
    )
  );

revoke all on table referrals, points_ledger, freebies, freebie_claims from public, anon, authenticated;
grant select on table referrals, points_ledger, freebies, freebie_claims to authenticated;
grant all on table referrals, points_ledger, freebies, freebie_claims to service_role;

-- p_min_points is checked inside the lock. A repeated request id is a no-op.
create or replace function redeem_points_to_wallet(
  p_customer_id uuid,
  p_points int,
  p_value_per_point bigint,
  p_request_id text,
  p_min_points int
)
returns table (success boolean, new_points int, new_balance bigint, error_code text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_balance bigint;
  v_points int;
  v_existing int;
  v_bot uuid;
  v_tenant uuid;
begin
  if p_request_id is null or length(trim(p_request_id)) = 0 then
    return query select false, 0, 0::bigint, 'REQUEST_REQUIRED';
    return;
  end if;

  select credit_balance, bot_id into v_balance, v_bot
  from customers
  where id = p_customer_id
  for update;

  if not found then
    return query select false, 0, 0::bigint, 'CUSTOMER_NOT_FOUND';
    return;
  end if;

  if v_bot is null then
    v_tenant := null;
  else
    select tenant_id into v_tenant from bot_connections where id = v_bot;
  end if;

  select delta into v_existing
  from points_ledger
  where customer_id = p_customer_id
    and reason = 'redeem_to_wallet'
    and reference = p_request_id;

  select coalesce(sum(delta), 0)::int into v_points
  from points_ledger
  where customer_id = p_customer_id;

  if v_existing is not null then
    return query select true, v_points, v_balance, null::text;
    return;
  end if;

  if p_points is null or p_points <= 0 or p_min_points is null or p_points < p_min_points then
    return query select false, v_points, v_balance, 'BELOW_MINIMUM';
    return;
  end if;

  if v_points < p_points then
    return query select false, v_points, v_balance, 'INSUFFICIENT_POINTS';
    return;
  end if;

  if p_value_per_point is null or p_value_per_point <= 0 then
    return query select false, v_points, v_balance, 'INVALID_VALUE';
    return;
  end if;

  insert into points_ledger (customer_id, tenant_id, delta, reason, reference)
  select p_customer_id, v_tenant, -p_points, 'redeem_to_wallet', p_request_id
  where not exists (
    select 1 from points_ledger
    where customer_id = p_customer_id and reason = 'redeem_to_wallet' and reference = p_request_id
  );

  if not found then
    select coalesce(sum(delta), 0)::int into v_points from points_ledger where customer_id = p_customer_id;
    return query select true, v_points, v_balance, null::text;
    return;
  end if;

  update customers
  set credit_balance = credit_balance + (p_points::bigint * p_value_per_point),
      updated_at = now()
  where id = p_customer_id
    and credit_balance + (p_points::bigint * p_value_per_point) >= 0
  returning credit_balance into v_balance;

  if not found then
    raise exception 'redeem balance update failed';
  end if;

  select coalesce(sum(delta), 0)::int into v_points from points_ledger where customer_id = p_customer_id;
  return query select true, v_points, v_balance, null::text;
end;
$$;

revoke all on function redeem_points_to_wallet(uuid, int, bigint, text, int) from public;
grant execute on function redeem_points_to_wallet(uuid, int, bigint, text, int) to service_role;

-- Locks the referrer, enforces the daily cap, and writes the reward once.
create or replace function grant_referral_reward(
  p_referral_id uuid,
  p_points int,
  p_daily_cap int,
  p_day_start timestamptz,
  p_order_id uuid
)
returns table (granted boolean, capped boolean, already boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ref referrals%rowtype;
  v_today int;
begin
  select * into v_ref from referrals where id = p_referral_id for update;
  if not found then
    return query select false, false, false;
    return;
  end if;

  perform 1 from customers where id = v_ref.referrer_customer_id for update;

  if v_ref.status = 'qualified' then
    return query select false, false, true;
    return;
  end if;
  if v_ref.status <> 'pending' then
    return query select false, false, false;
    return;
  end if;

  select count(*)::int into v_today
  from referrals
  where referrer_customer_id = v_ref.referrer_customer_id
    and status = 'qualified'
    and qualified_at >= p_day_start
    and qualified_at < p_day_start + interval '1 day';

  if p_daily_cap is not null and p_daily_cap >= 0 and v_today >= p_daily_cap then
    return query select false, true, false;
    return;
  end if;

  update referrals
  set status = 'qualified',
      qualified_order_id = p_order_id,
      qualified_at = now()
  where id = p_referral_id and status = 'pending';

  if not found then
    return query select false, false, true;
    return;
  end if;

  if p_points is not null and p_points > 0 then
    insert into points_ledger (customer_id, tenant_id, delta, reason, reference)
    values (v_ref.referrer_customer_id, v_ref.tenant_id, p_points, 'referral_reward', p_referral_id::text)
    on conflict (customer_id, reason, reference) do nothing;
  end if;

  return query select true, false, false;
end;
$$;

revoke all on function grant_referral_reward(uuid, int, int, timestamptz, uuid) from public;
grant execute on function grant_referral_reward(uuid, int, int, timestamptz, uuid) to service_role;
